import csv
import math
import statistics

def parse_amount(amount_str):
    if not isinstance(amount_str, str):
        return float('nan')
    s_trimmed = amount_str.strip()
    if not s_trimmed:
        return float('nan')

    is_negative = ("CR" in s_trimmed) or (s_trimmed.startswith('(') and s_trimmed.endswith(')')) or ("-" in s_trimmed)

    temp = s_trimmed.replace("C1", "").replace("C2", "")
    cleaned = "".join([c for c in temp if c.isdigit() or c in (',', '.')])
    if not cleaned:
        return float('nan')

    has_comma = ',' in cleaned
    has_dot = '.' in cleaned

    try:
        if has_comma and has_dot:
            last_comma_idx = cleaned.rfind(',')
            last_dot_idx = cleaned.rfind('.')
            if last_comma_idx > last_dot_idx:
                decimal_sep = ','
                thousands_sep = '.'
            else:
                decimal_sep = '.'
                thousands_sep = ','
            cleaned_parsed = cleaned.replace(thousands_sep, "").replace(decimal_sep, ".")
        elif has_comma:
            last_comma_idx = cleaned.rfind(',')
            if len(cleaned[last_comma_idx + 1:]) == 2:
                before_last = cleaned[:last_comma_idx].replace(',', '')
                after_last = cleaned[last_comma_idx + 1:]
                cleaned_parsed = before_last + '.' + after_last
            else:
                cleaned_parsed = cleaned.replace(',', '')
        elif has_dot:
            last_dot_idx = cleaned.rfind('.')
            if len(cleaned[last_dot_idx + 1:]) == 2:
                before_last = cleaned[:last_dot_idx].replace('.', '')
                after_last = cleaned[last_dot_idx + 1:]
                cleaned_parsed = before_last + '.' + after_last
            else:
                cleaned_parsed = cleaned.replace('.', '')
        else:
            cleaned_parsed = cleaned

        val = float(cleaned_parsed)
        if is_negative:
            val = -val
        return val
    except Exception:
        return float('nan')

def parse_notes(notes_str):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if not notes_str:
        return items, adj_pct, fee, waive

    parts = notes_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if '=' not in part:
            continue
        key, val = part.split('=', 1)
        key = key.strip().lower()
        val = val.strip()

        if key == 'items':
            try:
                items = int(val)
            except ValueError:
                items = None
        elif key == 'adj':
            val_clean = val.replace('%', '').strip()
            try:
                adj_pct = float(val_clean) / 100.0
            except ValueError:
                adj_pct = 0.0
        elif key == 'fee':
            try:
                fee = float(val)
            except ValueError:
                fee = 0.0
        elif key == 'waive':
            if val.lower() == 'true':
                waive = True

    return items, adj_pct, fee, waive

# Let's load the data
rows_all = []
with open('/app/dataset/data.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    for idx, row in enumerate(reader):
        record_id, event_time, region, channel, amount_str, notes_str = row
        base_amount = parse_amount(amount_str)
        items, adj_pct, fee, waive = parse_notes(notes_str)
        if math.isnan(base_amount):
            net = float('nan')
        elif waive:
            net = 0.0
        else:
            net = base_amount * (1.0 + adj_pct) + fee

        rows_all.append({
            'row_index': idx,
