            'notes_str': notes_str,
            'base_amount': base_amount,
            'items': items,
            'adj_pct': adj_pct,
            'fee': fee,
            'waive': waive,
            'net': net,
            'is_real_net': not math.isnan(net)
        })

print(f"Loaded {len(rows_all)} rows.")

def get_detailed_stats(filter_first):
    print(f"\n--- Stats for {'Filter First (Approach B)' if filter_first else 'Dedup First (Approach A)'} ---")
    if filter_first:
        # Filter first
        filtered_rows = []
        for r in rows_all:
            if not r['event_time']:
                continue
            if not ("2025-10-01T00:00:00Z" <= r['event_time'] <= "2025-12-31T23:59:59Z"):
                continue
            if r['channel'].lower() == 'phone':
                continue
            if math.isnan(r['net']) or math.isinf(r['net']):
                continue
            filtered_rows.append(r)
        print(f"Rows after filtering: {len(filtered_rows)}")

        by_record = {}
        for r in filtered_rows:
            rid = r['record_id']
            if rid not in by_record:
                by_record[rid] = r
            else:
                existing = by_record[rid]
                replace = False
                if r['event_time'] > existing['event_time']:
                    replace = True
                elif r['event_time'] == existing['event_time']:
                    if r['is_real_net'] and not existing['is_real_net']:
                        replace = True
                    elif r['is_real_net'] == existing['is_real_net']:
                        if r['row_index'] < existing['row_index']:
                            replace = True
                if replace:
                    by_record[rid] = r
        final_rows = list(by_record.values())
        print(f"Rows after deduplication: {len(final_rows)}")
    else:
