import csv
import math
import statistics
import json

def parse_amount(amount_str):
    if not isinstance(amount_str, str):
        return float('nan')
    s_trimmed = amount_str.strip()
    if not s_trimmed:
        return float('nan')

    # Check negative
    is_negative = ("CR" in s_trimmed) or (s_trimmed.startswith('(') and s_trimmed.endswith(')')) or ("-" in s_trimmed)

    # Remove C1 and C2, and strip letters and spaces
    temp = s_trimmed.replace("C1", "").replace("C2", "")
    cleaned = "".join([c for c in temp if c.isdigit() or c in (',', '.')])
    if not cleaned:
        return float('nan')

    has_comma = ',' in cleaned
    has_dot = '.' in cleaned

    try:
        if has_comma and has_dot:
            last_comma_idx = cleaned.rfind(',')
            last_dot_idx = cleaned.rfind('.')
            if last_comma_idx > last_dot_idx:
                decimal_sep = ','
                thousands_sep = '.'
            else:
                decimal_sep = '.'
                thousands_sep = ','
            cleaned_parsed = cleaned.replace(thousands_sep, "").replace(decimal_sep, ".")
        elif has_comma:
            last_comma_idx = cleaned.rfind(',')
            if len(cleaned[last_comma_idx + 1:]) == 2:
                before_last = cleaned[:last_comma_idx].replace(',', '')
                after_last = cleaned[last_comma_idx + 1:]
                cleaned_parsed = before_last + '.' + after_last
            else:
                cleaned_parsed = cleaned.replace(',', '')
        elif has_dot:
            last_dot_idx = cleaned.rfind('.')
            if len(cleaned[last_dot_idx + 1:]) == 2:
                before_last = cleaned[:last_dot_idx].replace('.', '')
                after_last = cleaned[last_dot_idx + 1:]
                cleaned_parsed = before_last + '.' + after_last
            else:
                cleaned_parsed = cleaned.replace('.', '')
        else:
            cleaned_parsed = cleaned

        val = float(cleaned_parsed)
        if is_negative:
            val = -val
        return val
    except Exception:
        return float('nan')

def parse_notes(notes_str):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if not notes_str:
        return items, adj_pct, fee, waive

    parts = notes_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if '=' not in part:
            continue
        key, val = part.split('=', 1)
        key = key.strip().lower()
        val = val.strip()

        if key == 'items':
            try:
                items = int(val)
            except ValueError:
                items = None
        elif key == 'adj':
            val_clean = val.replace('%', '').strip()
            try:
                adj_pct = float(val_clean) / 100.0
            except ValueError:
                adj_pct = 0.0
        elif key == 'fee':
            try:
                fee = float(val)
            except ValueError:
                fee = 0.0
        elif key == 'waive':
            if val.lower() == 'true':
                waive = True

    return items, adj_pct, fee, waive

def mergesort(arr, cmp):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = mergesort(arr[:mid], cmp)
    right = mergesort(arr[mid:], cmp)

    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if cmp(left[i], right[j]) <= 0:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

def compare_rows(row1, row2):
    # rank rows by anomaly_score descending, then abs(robust_z) descending,
    # then event_time descending, then record_id ascending
    if abs(row1['anomaly_score'] - row2['anomaly_score']) > 1e-12:
        return -1 if row1['anomaly_score'] > row2['anomaly_score'] else 1
    rz1 = abs(row1['robust_z'])
    rz2 = abs(row2['robust_z'])
    if abs(rz1 - rz2) > 1e-12:
        return -1 if rz1 > rz2 else 1
    if row1['event_time'] != row2['event_time']:
        return -1 if row1['event_time'] > row2['event_time'] else 1
    if row1['record_id'] != row2['record_id']:
        return -1 if row1['record_id'] < row2['record_id'] else 1
    return 0

def answer() -> list[str]:
    # Load dataset
    rows_all = []
    with open('/app/dataset/data.csv', 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        for idx, row in enumerate(reader):
            record_id, event_time, region, channel, amount_str, notes_str = row
            base_amount = parse_amount(amount_str)
            items, adj_pct, fee, waive = parse_notes(notes_str)
            if math.isnan(base_amount):
                net = float('nan')
            elif waive:
                net = 0.0
            else:
                net = base_amount * (1.0 + adj_pct) + fee

            rows_all.append({
                'row_index': idx,
                'record_id': record_id,
                'event_time': event_time.strip(),
                'region': region.strip(),
                'channel': channel.strip(),
                'amount_str': amount_str,
                'notes_str': notes_str,
                'base_amount': base_amount,
                'items': items,
                'adj_pct': adj_pct,
                'fee': fee,
                'waive': waive,
                'net': net,
                'is_real_net': not math.isnan(net)
            })

    # Deduplicate over the entire dataset first (Approach A)
    by_record = {}
    for r in rows_all:
        rid = r['record_id']
        if rid not in by_record:
            by_record[rid] = r
        else:
            existing = by_record[rid]
            replace = False
            t_new = r['event_time']
            t_existing = existing['event_time']
            if t_new > t_existing:
                replace = True
            elif t_new == t_existing:
                r_real = r['is_real_net']
                ex_real = existing['is_real_net']
                if r_real and not ex_real:
                    replace = True
                elif r_real == ex_real:
                    if r['row_index'] < existing['row_index']:
                        replace = True
            if replace:
                by_record[rid] = r

    # Filter deduplicated rows
    final_rows = []
    for r in by_record.values():
        if not r['event_time']:
            continue
        # event_time between 2025-10-01 00:00:00 and 2025-12-31 23:59:59 inclusive
        if not ("2025-10-01T00:00:00Z" <= r['event_time'] <= "2025-12-31T23:59:59Z"):
            continue
        # channel != "phone" (case-insensitive)
        if r['channel'].lower() == 'phone':
            continue
        # finite net
        if math.isnan(r['net']) or math.isinf(r['net']):
            continue
        final_rows.append(r)

    # Group by (region, month) and compute robust z-score
    groups = {}
    for r in final_rows:
        month = r['event_time'][:7]
        group_key = (r['region'], month)
        if group_key not in groups:
            groups[group_key] = []
        groups[group_key].append(r)

    for group_key, g_rows in groups.items():
        net_values = [r['net'] for r in g_rows]
        med = statistics.median(net_values)
        deviations = [abs(net - med) for net in net_values]
        mad = statistics.median(deviations)

        for r in g_rows:
            if mad == 0:
                robust_z = 0.0
            else:
                robust_z = 0.6745 * (r['net'] - med) / mad
            r['robust_z'] = robust_z

            # items_eff
            items = r['items']
            items_eff = max(items, 1) if items is not None else 1
            r['anomaly_score'] = abs(robust_z) * math.log1p(items_eff)

    # Sort using stable mergesort
    sorted_rows = mergesort(final_rows, compare_rows)
    return [r['record_id'] for r in sorted_rows[:10]]

if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

